#!/usr/bin/env bash
# Disables PIN-gate enforcement on the Admin Panel's own web dashboard
# login. That gate was built for the wrong user base — it was meant for
# actual kiosk-terminal usage, not fleet managers logging into
# kiosksys.opslabsystems.cloud. No migration, no schema change - this
# only touches app/__init__.py's before_request hook.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/__init__.py "backups/$TS/__init__.py.bak" 2>/dev/null || true
echo "==> Backed up existing file to backups/$TS/"

echo "==> Writing app/__init__.py"
base64 -d > app/__init__.py << 'INIT_PY_B64'

INIT_PY_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/__init__.py').read())"
echo "    syntax OK"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "PIN gate disabled. Nobody is required to set a PIN to use the"
echo "dashboard anymore - log in and confirm you land straight on your"
echo "company page, no PIN screen."
echo "==================================================================="
